import React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { bubbleStyleKeys, getBubbleStyleKeys } from '../lib/core';
import type { BubbleBaseProps, BubbleContentBaseProps, BubbleReactionsBaseProps } from '../lib/core';
import styles from './bubble.module.scss';

export interface BubbleGroupProps extends React.HTMLAttributes<HTMLDivElement> {}

const BubbleGroup = React.forwardRef<HTMLDivElement, BubbleGroupProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} data-slot="bubble-group" className={[styles[bubbleStyleKeys.group], className].filter(Boolean).join(' ')} {...props}>
			{children}
		</div>
	);
});
BubbleGroup.displayName = 'BubbleGroup';

export interface BubbleProps extends React.HTMLAttributes<HTMLDivElement>, BubbleBaseProps {}

const Bubble = React.forwardRef<HTMLDivElement, BubbleProps>(({ className = '', variant = 'default', align = 'start', children, ...props }, ref) => {
	const styleKeys = getBubbleStyleKeys(variant);

	return (
		<div
			ref={ref}
			data-slot="bubble"
			data-variant={variant}
			data-align={align}
			className={[styles[styleKeys.base], styles[styleKeys.variant], className].filter(Boolean).join(' ')}
			{...props}>
			{children}
		</div>
	);
});
Bubble.displayName = 'Bubble';

export interface BubbleContentProps extends React.HTMLAttributes<HTMLDivElement>, BubbleContentBaseProps {}

const BubbleContent = React.forwardRef<HTMLDivElement, BubbleContentProps>(({ className = '', asChild = false, children, ...props }, ref) => {
	const Comp = asChild ? Slot : 'div';

	return (
		<Comp ref={ref} data-slot="bubble-content" className={[styles[bubbleStyleKeys.content], className].filter(Boolean).join(' ')} {...props}>
			{children}
		</Comp>
	);
});
BubbleContent.displayName = 'BubbleContent';

export interface BubbleReactionsProps extends React.HTMLAttributes<HTMLDivElement>, BubbleReactionsBaseProps {}

const BubbleReactions = React.forwardRef<HTMLDivElement, BubbleReactionsProps>(({ className = '', side = 'bottom', align = 'end', children, ...props }, ref) => {
	return (
		<div
			ref={ref}
			data-slot="bubble-reactions"
			data-side={side}
			data-align={align}
			className={[styles[bubbleStyleKeys.reactions], className].filter(Boolean).join(' ')}
			{...props}>
			{children}
		</div>
	);
});
BubbleReactions.displayName = 'BubbleReactions';

export { BubbleGroup, Bubble, BubbleContent, BubbleReactions };
export default Bubble;

@use '../../../styles/variables/colors' as *;

// 气泡组
.group {
	display: flex;
	width: 100%;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-2;
}

// 气泡根容器
.bubble {
	position: relative;
	display: flex;
	width: fit-content;
	max-width: 80%;
	min-width: 0;
	flex-direction: column;
	gap: $spacing-1;

	&[data-align='end'] {
		align-self: flex-end;

		.content {
			align-self: flex-end;
		}
	}

	&[data-variant='ghost'] {
		max-width: 100%;
	}

	&:has(.reactions[data-side='top']) {
		margin-top: $spacing-3;
	}

	&:has(.reactions[data-side='bottom']) {
		margin-bottom: $spacing-3;
	}

	// 变体
	&.variantDefault .content {
		background-color: var(--tile-bubble-background, $primary);
		color: var(--tile-bubble-color, $primary-foreground);
	}

	&.variantSecondary .content {
		background-color: var(--tile-bubble-secondary-background, $secondary);
		color: $secondary-foreground;
	}

	&.variantMuted .content {
		background-color: var(--tile-bubble-muted-background, $muted);
		color: $foreground;
	}

	&.variantTinted .content {
		background-color: var(--tile-bubble-tinted-background, color-mix(in srgb, $primary 15%, $background));
		color: $foreground;
	}

	&.variantOutline .content {
		border-color: var(--tile-bubble-border, $border);
		background-color: var(--tile-bubble-outline-background, $background);
		color: $foreground;
	}

	&.variantGhost .content {
		border: none;
		border-radius: 0;
		background-color: transparent;
		padding: 0;
	}

	&.variantDestructive .content {
		background-color: var(--tile-bubble-error-background, color-mix(in srgb, $destructive 10%, transparent));
		color: var(--tile-bubble-error-color, $destructive);
	}

	// 按钮/链接形态的内容悬停效果
	&.variantDefault .content:is(button, a):hover {
		background-color: var(--tile-bubble-hover-background, color-mix(in srgb, $primary 80%, transparent));
	}

	&.variantSecondary .content:is(button, a):hover,
	&.variantMuted .content:is(button, a):hover,
	&.variantGhost .content:is(button, a):hover,
	&.variantOutline .content:is(button, a):hover {
		background-color: $muted;
		color: $foreground;
	}

	&.variantDestructive .content:is(button, a):hover {
		background-color: var(--tile-bubble-error-hover-background, color-mix(in srgb, $destructive 20%, transparent));
	}
}

// 气泡内容
.content {
	display: block;
	width: fit-content;
	max-width: 100%;
	min-width: 0;
	overflow: hidden;
	border: 1px solid transparent;
	border-radius: var(--tile-bubble-radius, $radius);
	padding: var(--tile-bubble-padding, $spacing-2 $spacing-3);
	font-size: $text-sm;
	line-height: $leading-relaxed;
	overflow-wrap: anywhere;
	word-break: break-word;

	&:is(button, a) {
		text-align: left;
		transition:
			background-color $transition-fast,
			border-color $transition-fast,
			box-shadow $transition-fast;
		outline: none;
	}

	&:is(button, a):focus-visible {
		border-color: $ring;
		box-shadow: var(--tile-bubble-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}
}

// 气泡反应区 (绝对定位于气泡边缘)
.reactions {
	position: absolute;
	z-index: 10;
	display: flex;
	width: fit-content;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	border-radius: $radius-full;
	background-color: var(--tile-bubble-reactions-background, $muted);
	padding: 0.125rem $spacing-1_5;
	font-size: $text-sm;
	box-shadow: 0 0 0 3px $card;

	&[data-side='top'] {
		top: 0;
		transform: translateY(-75%);
	}

	&[data-side='bottom'] {
		bottom: 0;
		transform: translateY(75%);
	}

	&[data-align='start'] {
		left: $spacing-3;
	}

	&[data-align='end'] {
		right: $spacing-3;
	}
}
